}

solution:
function memberNames(enumObject: Record<string, string | number>): string[] {
  return Object.keys(enumObject).filter(key => {
    const value = enumObject[key];
    // A reverse mapping is a numeric key whose string value maps back to that number.
    const isReverse = typeof value === 'string' && enumObject[value] === Number(key);
    return !isReverse;
  });
}

