const LogLevel = { Debug: 'debug', Info: 'info', Warn: 'warn', Error: 'error' } as const;
type Level = (typeof LogLevel)[keyof typeof LogLevel];

const LEVELS: readonly string[] = Object.values(LogLevel);

function isLevel(value: string): value is Level {
  return LEVELS.includes(value);
}

function parseLevel(input: string): Level | null {
  const value = input.trim().toLowerCase();
  return isLevel(value) ? value : null;
}

type Shape =
  | { kind: 'circle'; r: number }
  | { kind: 'square'; side: number }
  | { kind: 'rect'; w: number; h: number };

function assertNever(value: never): never {
  throw new Error(`Unexpected shape: ${JSON.stringify(value)}`);
}

function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle': return Math.round(Math.PI * shape.r ** 2 * 100) / 100;
    case 'square': return shape.side ** 2;
    case 'rect': return shape.w * shape.h;
    default: return assertNever(shape);
  }
}

